// arrNestedMaxBytes. Returns the bytes written, or -1 when a count is outside its
// wire range, which is refused in every build (SPEC §4.6).
int writeArrNested(ArrNested value, ByteData view) {
  assert(view.lengthInBytes % 8 == 0);
  assert(view.lengthInBytes >= arrNestedMaxBytes);
  var scratch = 0;
  var scratchBits = 0;
  var wordIndex = 0;
  var v = 0;
  if (value.itemsCount < 0 || value.itemsCount > 4) {
    return -1; // a count outside its wire range is refused in every build (SPEC §4.6)
  }
  v = ((value.lead) & 0x1f) | (((value.itemsCount) & 0x7) << 5);
  scratch |= v << scratchBits;
  scratchBits += 8;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (8 - scratchBits);
  }
  {
    var i0 = 0;
    for (; i0 + 5 <= value.itemsCount; i0 += 5) {
      final e0 = value.items[i0];
      final e0g1 = value.items[i0 + 1];
      final e0g2 = value.items[i0 + 2];
      final e0g3 = value.items[i0 + 3];
      final e0g4 = value.items[i0 + 4];
      v =
          ((e0.a) & 0x7) |
          (((e0.b) & 0xff) << 3) |
          (((e0g1.a) & 0x7) << 11) |
          (((e0g1.b) & 0xff) << 14) |
          (((e0g2.a) & 0x7) << 22) |
          (((e0g2.b) & 0xff) << 25) |
          (((e0g3.a) & 0x7) << 33) |
          (((e0g3.b) & 0xff) << 36) |
          (((e0g4.a) & 0x7) << 44) |
          (((e0g4.b) & 0xff) << 47);
      scratch |= v << scratchBits;
      scratchBits += 55;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = v >>> (55 - scratchBits);
      }
    }
    for (; i0 < value.itemsCount; i0++) {
      final e0 = value.items[i0];
      v = ((e0.a) & 0x7) | (((e0.b) & 0xff) << 3);
      scratch |= v << scratchBits;
      scratchBits += 11;
      if (scratchBits >= 64) {
        view.setUint64(wordIndex * 8, scratch, Endian.little);
        wordIndex++;
        scratchBits -= 64;
        scratch = v >>> (11 - scratchBits);
      }
    }
  }
  v = ((value.tail) & 0x7);
  scratch |= v << scratchBits;
  scratchBits += 3;
  if (scratchBits >= 64) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
    wordIndex++;
    scratchBits -= 64;
    scratch = v >>> (3 - scratchBits);
  }
  if (scratchBits != 0) {
    view.setUint64(wordIndex * 8, scratch, Endian.little);
  }
  return wordIndex * 8 + ((scratchBits + 7) >>> 3);
}

// readArrNested decodes value from the first numBits of view — the family read
// verdict: false rejects the wire (bounds, ranges, wire constants, padding);
// hostile bytes never throw. No slack past the payload is required.
bool readArrNested(ArrNested value, ByteData view, int numBits) {
  if (numBits > view.lengthInBytes * 8) {
    return false; // the payload cannot exceed the buffer behind view
  }
  // the final 64-bit window, assembled once so every load stays inside
  // the buffer (serialize.dart's own no-slack reader stance)
  var tailBase = view.lengthInBytes - 8;
  var tailWord = 0;
  if (tailBase >= 0) {
    tailWord = view.getUint64(tailBase, Endian.little);
  } else {
    tailBase = 0;
    for (var i = view.lengthInBytes - 1; i >= 0; i--) {
      tailWord = (tailWord << 8) | view.getUint8(i);
    }
  }
  var bitsRead = 0;
  var window = 0;
  var v = 0;
  if (bitsRead + 5 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x1f;
  bitsRead += 5;
  value.lead = v;
  if (bitsRead + 3 > numBits) {
    return false;
  }
  v = (window >>> 5) & 0x7;
  bitsRead += 3;
  if (v > 4) {
    return false; // the count guards the loop — reject, never clamp
  }
  value.itemsCount = v;
  if (bitsRead + value.itemsCount * 11 > numBits) {
    return false;
  }
  {
    var i0 = 0;
    for (; i0 + 5 <= value.itemsCount; i0 += 5) {
      final e0 = value.items[i0];
      if (bitsRead >>> 3 < tailBase) {
        window =
            view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
      } else {
        window = tailWord >>> (bitsRead - tailBase * 8);
      }
      v = window & 0x7;
      bitsRead += 3;
      e0.a = v;
      v = (window >>> 3) & 0xff;
      bitsRead += 8;
      e0.b = v;
      final e0g1 = value.items[i0 + 1];
      v = (window >>> 11) & 0x7;
      bitsRead += 3;
      e0g1.a = v;
      v = (window >>> 14) & 0xff;
      bitsRead += 8;
      e0g1.b = v;
      final e0g2 = value.items[i0 + 2];
      v = (window >>> 22) & 0x7;
      bitsRead += 3;
      e0g2.a = v;
      v = (window >>> 25) & 0xff;
      bitsRead += 8;
      e0g2.b = v;
      final e0g3 = value.items[i0 + 3];
      v = (window >>> 33) & 0x7;
      bitsRead += 3;
      e0g3.a = v;
      v = (window >>> 36) & 0xff;
      bitsRead += 8;
      e0g3.b = v;
      final e0g4 = value.items[i0 + 4];
      v = (window >>> 44) & 0x7;
      bitsRead += 3;
      e0g4.a = v;
      v = (window >>> 47) & 0xff;
      bitsRead += 8;
      e0g4.b = v;
    }
    for (; i0 < value.itemsCount; i0++) {
      final e0 = value.items[i0];
      if (bitsRead >>> 3 < tailBase) {
        window =
            view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
      } else {
        window = tailWord >>> (bitsRead - tailBase * 8);
      }
      v = window & 0x7;
      bitsRead += 3;
      e0.a = v;
      v = (window >>> 3) & 0xff;
      bitsRead += 8;
      e0.b = v;
    }
  }
  if (bitsRead + 3 > numBits) {
    return false;
  }
  if (bitsRead >>> 3 < tailBase) {
    window = view.getUint64(bitsRead >>> 3, Endian.little) >>> (bitsRead & 7);
  } else {
    window = tailWord >>> (bitsRead - tailBase * 8);
  }
  v = window & 0x7;
  bitsRead += 3;
  value.tail = v;
  return true;
}

// measureArrNested is the exact wire bits writeArrNested would produce for value —
// trusted like the writer; static runs fold to literals at generation time.
int measureArrNested(ArrNested value) {
  var bits = 0;
  bits += 8;
  bits += value.itemsCount * 11;
  bits += 3;
  return bits;
}

